function icon(name,cls=''){return `<svg class="${cls}" viewBox="0 0 24 24" aria-hidden="true">${icons[name]||icons.leaf}</svg>`}
function botanical(cls=''){return `<svg class="botanical ${cls}" viewBox="0 0 160 240" aria-hidden="true"><g stroke="currentColor" stroke-width=".9" fill="none"><path d="M70 240C95 181 62 102 100 10M80 204 29 146M83 169l48-65M79 124 38 79M86 83l48-42M91 55 75 23"/><path fill="currentColor" fill-opacity=".12" d="M78 202C35 207 5 174 8 128c34 8 63 31 70 74ZM83 169c-6-45 28-65 65-80-1 42-20 71-65 80ZM79 124C39 128 19 103 23 57c29 12 52 31 56 67ZM87 83c6-35 29-48 61-54-9 31-29 50-61 54ZM91 55C62 53 59 34 68 7c15 13 24 28 23 48ZM98 29c-4-17 3-24 16-28 3 15-3 24-16 28Z"/><path d="M76 197 17 140M28 148l-1 20M39 161l-1 24M51 173l2 22M35 156l-17-1M49 169l-23 1M63 183l-24 2M87 161l51-61M104 139l1-24M115 125l1-19M97 148l23-3M108 134l24-4M78 117 29 66M42 80l-1 22M53 93l-1 19M51 90l-17-1M64 103l-23-1M92 75l47-39M109 59l2-17M116 52l17-1M90 50 70 14"/><path d="M72 236c-17-3-23-17-17-30 13 6 18 16 17 30ZM79 220c23-5 34-19 31-39-20 8-31 21-31 39Z"/></g></svg>`}
function portrait(n=0){const colors=[['#e5e7d8','#6a4c3b','#e7bfa0','#788b70'],['#eae0d4','#4b3b31','#dfb08f','#a78a6b'],['#e0e6de','#a37c50','#edc7a6','#627c73'],['#e4ddd4','#3f322c','#d6a182','#8b8873']][n%4];return `<svg class="portrait" viewBox="0 0 400 280" aria-hidden="true"><rect width="400" height="280" fill="${colors[0]}"/><g opacity=".27" stroke="#7f9070" fill="none" stroke-width="1"><path d="M45 280Q90 130 43 20M65 190Q15 160 20 118Q65 136 65 190ZM65 146Q108 126 105 84Q68 96 65 146ZM58 99Q23 83 25 45Q55 63 58 99ZM332 280Q300 130 363 25M322 199Q363 169 363 126Q322 140 322 199ZM322 137Q289 119 296 77Q326 96 322 137Z"/></g><path d="M119 280c0-71 34-101 81-101s81 30 81 101Z" fill="${colors[3]}"/><path d="M170 162h60v43c-19 22-42 22-60 0Z" fill="${colors[2]}"/><path d="M134 129c-4-63 13-104 66-104s77 44 66 109l-21 60h-91Z" fill="${colors[1]}"/><ellipse cx="200" cy="115" rx="51" ry="64" fill="${colors[2]}"/><path d="M144 112c5-71 82-97 112-26-31-2-50-16-59-29-9 25-27 41-53 55Z" fill="${colors[1]}"/><path d="M171 119q8-6 14 0M216 119q8-6 14 0M188 150q12 9 24 0" stroke="#805b48" stroke-width="2" fill="none" stroke-linecap="round"/><path d="M199 121l-4 14h7" stroke="#bc8a6a" stroke-width="1.2" fill="none"/><path d="M148 242q52 23 104 0" stroke="#f7f2e5" stroke-width="1.5" fill="none" opacity=".5"/><path d="M165 180q35 27 70 0" stroke="#c59171" stroke-width="1" fill="none"/></svg>`}
const defaults={name:'Светлана',child:'Малыш',city:'Екатеринбург',interests:'Прогулки, книги, спокойные разговоры',age:null,saved:[],mood:null,moodDate:null,likes:[],matches:[]};
let persisted={};try{persisted=JSON.parse(localStorage.getItem('trimester-v1')||'{}')||{}}catch{};
const state={...defaults,...persisted};
if(![null,1,3,6,12].includes(state.age))state.age=null;
for(const k of ['saved','likes','matches'])if(!Array.isArray(state[k]))state[k]=[];
const save=()=>{try{localStorage.setItem('trimester-v1',JSON.stringify(state))}catch{toast('Браузер не разрешил сохранить изменения')}};
const sources={hygiene:'https://www.nhs.uk/baby/caring-for-a-newborn/washing-and-bathing-your-baby/',nappy:'https://www.nhs.uk/baby/caring-for-a-newborn/how-to-change-your-babys-nappy/',sleep:'https://www.nhs.uk/baby/caring-for-a-newborn/helping-your-baby-to-sleep/',urgent:'https://www.nhs.uk/baby/health/when-to-get-urgent-medical-help-for-babies-and-children-under-5/',feed:'https://www.nhs.uk/baby/breastfeeding-and-bottle-feeding/breastfeeding/positioning-and-attachment/',solids:'https://www.nhs.uk/baby/weaning-and-feeding/babys-first-solid-foods/',body:'https://www.nhs.uk/pregnancy/labour-and-birth/your-body/',mind:'https://www.nhs.uk/mental-health/conditions/postnatal-depression/'};
const articles=[
{id:'wash',owner:'baby',cat:'Гигиена',title:'Как подмыть малыша',desc:'Тёплая вода, мягкое полотенце и ваши руки. Всё, что нужно для начала.',icon:'water',time:3,ages:[1,3,6,12],steps:['Приготовьте воду, чистый подгузник и полотенце. Вымойте руки. Удобнее устроить малыша на безопасной поверхности, например на коврике на полу.','Мягко очистите кожу водой или салфеткой без спирта и запаха. У девочки двигайтесь спереди назад. У мальчика не оттягивайте крайнюю плоть.','Промокните кожу, особенно складочки. Наденьте чистый подгузник и снова вымойте руки.'],takeaway:'Не нужно тереть кожу. Достаточно мягких движений.',source:'nappy'},
{id:'bath',owner:'baby',cat:'Гигиена',title:'Первая ванна без волнения',desc:'Подготовим всё заранее, чтобы спокойно побыть рядом с малышом.',icon:'water',time:3,ages:[1,3],steps:['Положите полотенце и одежду рядом. В комнате должно быть тепло. Вода — тёплая, не горячая. Перемешайте её и проверьте локтем.','Поддерживайте голову и плечи одной рукой. Другой осторожно мойте малыша. Голову держите над водой.','Достаньте ребёнка и промокните полотенцем, включая складочки. Не оставляйте малыша в воде одного ни на секунду.'],takeaway:'Ежедневная ванна необязательна. Можно аккуратно умыть лицо, шею, руки и область подгузника.',source:'hygiene'},
{id:'vaccine',owner:'baby',cat:'Вакцинация',title:'Как подготовиться к прививке',desc:'Небольшой список вопросов для педиатра вместо поиска в десятке чатов.',icon:'shield',time:2,ages:[1,3,6,12],steps:['Возьмите документы о прошлых прививках. Запишите, что хотите спросить у врача.','Расскажите о самочувствии ребёнка и прежних реакциях. Уточните, какая вакцина планируется и зачем.','Попросите записать дату следующего визита и объяснить, при каких симптомах обращаться за помощью.'],takeaway:'Календарь зависит от страны, полученных доз и здоровья ребёнка. Здесь нет персонального назначения: согласуйте даты с педиатром.',source:null},
{id:'latch',owner:'baby',cat:'Кормление',title:'Удобно устроиться для кормления',desc:'Вы с малышом учитесь вместе. Не обязательно уметь всё с первого раза.',icon:'feeding',time:3,ages:[1,3],steps:['Сядьте так, чтобы плечи и руки могли расслабиться. При необходимости подложите подушку.','Расположите голову и тело малыша на одной линии. Держите его близко к себе, нос — на уровне соска.','Поднесите малыша к груди, а не наклоняйтесь к нему. Дайте ему широко открыть рот.'],takeaway:'Если больно или трудно прикладывать ребёнка, попросите акушерку или консультанта по кормлению показать лично.',source:'feed'},
{id:'nappy',owner:'baby',cat:'Выделения',title:'Что можно заметить в подгузнике',desc:'Подгузник помогает наблюдать за малышом, но сам по себе не ставит диагноз.',icon:'leaf',time:2,ages:[1,3,6,12],steps:['В первые дни стул может быть липким и почти чёрным. Позже его вид меняется и зависит от питания.','Важна перемена по сравнению с обычным стулом вашего малыша. Частота сама по себе не объясняет, здоров ли ребёнок.','Кровь, необычно бледный стул или заметное изменение консистенции — повод связаться с врачом.'],takeaway:'В чате можно поделиться переживаниями. Оценивать симптомы должен педиатр.',source:'nappy'},
{id:'urgent',owner:'baby',cat:'Заболевания',title:'Когда нужна срочная помощь',desc:'Несколько признаков, при которых не стоит ждать ответа в чате.',icon:'health',time:2,ages:[1,3,6,12],steps:['Малышу меньше 3 месяцев, а температура 38 °C или выше? Нужен срочный медицинский осмотр.','Тяжело дышать, ребёнка трудно разбудить, есть судороги или синеют губы? Вызывайте экстренную помощь.','Если ребёнок выглядит серьёзно больным, обращайтесь за помощью сразу, даже если нет всех перечисленных признаков.'],takeaway:'При непосредственной угрозе жизни звоните 112 в России и ЕС или в местную экстренную службу.',source:'urgent'},
{id:'sleep',owner:'baby',cat:'Сон',title:'Тихий ритуал перед сном',desc:'Несколько знакомых действий помогают отличать день от ночи.',icon:'moon',time:2,ages:[1,3,6,12],steps:['Днём оставляйте обычный свет и повседневные звуки. Ночью приглушите свет и говорите тише.','Выберите простой порядок: чистый подгузник, ночная одежда, спокойная песенка.','В первые полгода ребёнку лучше спать в одной комнате с вами.'],takeaway:'Ритуал — не экзамен. Он может быть коротким и меняться вместе с ребёнком.',source:'sleep'},
{id:'play',owner:'baby',cat:'Развитие',title:'Общение в обычных делах',desc:'Для близости не нужны специальные карточки и сложный план занятий.',icon:'sun',time:2,ages:[3,6,12],steps:['Расскажите, что делаете, пока переодеваете малыша. Можно просто назвать одежду и части тела.','Посмотрите на него, улыбнитесь, ответьте на его звуки. Дайте время откликнуться.','Если малыш отворачивается или устал, сделайте паузу. Ничего не нужно доделывать по расписанию.'],takeaway:'Ваше внимание — уже общение. Превращать каждую минуту в занятие необязательно.',source:'nappy'},
{id:'solids',owner:'baby',cat:'Прикорм',title:'Первые ложки: без спешки',desc:'Примерно с шести месяцев малыш знакомится с новой едой.',icon:'feeding',time:3,ages:[6,12],steps:['Ориентируйтесь не только на возраст: малыш должен удерживать голову, сидеть и координировать движения, чтобы брать пищу и глотать её.','Начните с небольшого количества. Молоко или смесь пока остаются важной частью питания. Не заставляйте доедать.','Посадите ребёнка вертикально и всё время оставайтесь рядом. Не давайте целые орехи и твёрдые кусочки сырых яблок или моркови.'],takeaway:'Если ребёнок родился раньше срока, обсудите время начала прикорма с педиатром.',source:'solids'},
{id:'table',owner:'baby',cat:'Питание',title:'За общим столом с малышом',desc:'Новые вкусы — в своём темпе и с вашим вниманием.',icon:'feeding',time:2,ages:[12],steps:['Предлагайте разнообразную еду подходящей мягкости. Отказ сегодня не означает отказ навсегда.','Ешьте вместе, если получается. Дайте малышу потрогать еду и попробовать есть самостоятельно.','Проверяйте, нет ли косточек и твёрдых частей. Маленькие круглые продукты разрежьте на четыре части. Оставайтесь рядом.'],takeaway:'Не добавляйте сахар и соль в детскую еду. Важнее знакомство с едой, чем пустая тарелка.',source:'solids'},
{id:'beauty',owner:'mom',cat:'Бьюти',title:'Уход, на который есть силы',desc:'Не новая обязанность, а маленький приятный момент для себя.',icon:'flower',time:2,format:'article',steps:['Спросите себя: что мне сейчас приятно? Умыться, расчесать волосы или просто побыть в тишине — подойдёт любой ответ.','Оставьте один удобный шаг. Не нужно собирать длинный ритуал и покупать новые средства.','Если уход сегодня не помещается в день, его можно пропустить. Это ничего не говорит о вашей ценности.'],takeaway:'Лечение кожи и совместимость средств с кормлением обсуждайте с врачом. Здесь — только идея бережного отношения к себе.',source:null},
{id:'body',owner:'mom',cat:'Тело',title:'Телу нужно своё время',desc:'Восстановление после родов не должно превращаться в гонку.',icon:'body',time:3,format:'article',steps:['Живот после родов может оставаться больше прежнего: мышцы были растянуты. Не требуйте от себя немедленного возвращения формы.','На послеродовом приёме расскажите о боли, недержании и том, что вас беспокоит.','Подбирайте нагрузку с учётом состояния и рекомендаций врача. После кесарева сечения нужен отдельный план восстановления.'],takeaway:'Боль и дискомфорт заслуживают внимания. Вам не нужно терпеть и справляться в одиночку.',source:'body'},
{id:'body-signs',owner:'mom',cat:'Заболевания',title:'Симптомы, с которыми не ждут',desc:'Сохраните этот короткий список и покажите близкому человеку.',icon:'health',time:2,format:'article',steps:['Боль в груди или трудности с дыханием после родов — повод для экстренной помощи.','Очень сильное кровотечение, слабость или предобморок тоже требуют срочной оценки.','Боль и отёк одной голени, высокая температура с болью в животе или головная боль с нарушением зрения — срочно обращайтесь за медицинской помощью.'],takeaway:'Не пытайтесь поставить себе диагноз по этому списку. При угрозе жизни звоните 112 в России и ЕС или в местную экстренную службу.',source:'body'},
{id:'breast',owner:'mom',cat:'Кормление грудью',title:'Когда кормить неудобно',desc:'Удобная поза — забота и о малыше, и о вас.',icon:'feeding',time:2,format:'article',steps:['Проверьте, не подняты ли плечи и не тянетесь ли вы к малышу. Устройтесь с опорой для рук.','Приблизьте ребёнка к себе. Поддерживайте шею, плечи и спину, не прижимая затылок.','Если не получается удобно или кормление болезненно, обратитесь за очной помощью с прикладыванием.'],takeaway:'Просить о помощи с кормлением нормально. Это навык, которому вы учитесь вместе.',source:'feed'},
{id:'mind',owner:'mom',cat:'Эмоции',title:'Когда «мне тяжело» — уже повод',desc:'Для обращения за поддержкой не нужно ждать, пока станет совсем плохо.',icon:'heart',time:3,format:'article',steps:['Заметьте, что происходит: тревожно, ничего не радует, трудно спать даже при возможности отдохнуть? Расскажите врачу.','Если подавленность после родов длится больше двух недель, усиливается или вам трудно справляться, обратитесь за помощью.','Попросите близкого человека о конкретной поддержке: взять прогулку, приготовить еду, помочь записаться к специалисту.'],takeaway:'Мысли о вреде себе или ребёнку требуют срочной поддержки. При риске действовать сейчас обратитесь в экстренную службу.',source:'mind'},
{id:'pause',owner:'mom',cat:'Эмоции',title:'Можно попросить о помощи',desc:'Короткая аудиозаметка о том, что вам не обязательно справляться одной.',icon:'audio',time:2,format:'podcast',steps:['Иногда трудно даже сформулировать просьбу. Попробуйте начать с одной простой фразы: «Мне сейчас тяжело».','Добавьте конкретное действие: «Побудь с малышом, пока я отдохну» или «Помоги мне записаться к врачу».','Поддержка может быть бытовой и профессиональной. Если тяжело долго или состояние ухудшается, обсудите это с врачом.'],takeaway:'Забота о вас — часть заботы о семье.',source:'mind'},
{id:'ritual',owner:'mom',cat:'Бьюти',title:'Пять минут только для себя',desc:'Аудиозаметка о маленьком личном пространстве внутри большого дня.',icon:'audio',time:1,format:'podcast',steps:['Выберите то, что вам приятно: тёплый напиток, музыка, взгляд в окно. Не то, что вы обязаны успеть.','Если есть возможность, попросите близкого взрослого побыть с малышом.','Эти минуты не нужно делать полезными. Можно просто посидеть. И можно попробовать в другой день.'],takeaway:'Маленькая пауза — приглашение, а не ещё один пункт в списке дел.',source:null},
{id:'rest',owner:'mom',cat:'Тело',title:'Отдых тоже имеет значение',desc:'Аудиозаметка о разрешении замедлиться и распределять заботу.',icon:'audio',time:1,format:'podcast',steps:['Восстановление требует времени. Постарайтесь оставить место для отдыха там, где это возможно.','Разделите бытовые дела с близкими. Просить о покупке продуктов или помощи с ребёнком — нормально.','Если усталость сопровождается стойкой подавленностью, тревогой или бессонницей, расскажите об этом специалисту.'],takeaway:'Вам можно быть человеком со своими потребностями.',source:'mind'}
];
