const moms=[{id:'anna',name:'Анна',age:29,child:'Сыну 4 месяца',city:'Екатеринбург',bio:'Ищу компанию для неспешных прогулок. Люблю книги, кофе без спешки и разговоры обо всём — не только о подгузниках.',tags:['Прогулки','Книги','Кофе'],portrait:0,likesYou:true},{id:'maria',name:'Мария',age:27,child:'Дочке 2 месяца',city:'Екатеринбург',bio:'Осваиваю материнство без идеальных планов. Буду рада подруге, с которой можно посмеяться и разделить обычный день.',tags:['Музыка','Кино','Прогулки'],portrait:1,likesYou:false},{id:'elena',name:'Елена',age:32,child:'Сыну 8 месяцев',city:'Екатеринбург',bio:'Собираю маленькие радости: парки, хорошие истории и домашние завтраки. Давайте гулять вместе!',tags:['Природа','Книги','Готовка'],portrait:2,likesYou:true},{id:'olga',name:'Ольга',age:30,child:'Дочке 1 год',city:'Екатеринбург',bio:'Люблю творчество и прогулки. Ищу общение без сравнения наших детей и достижений.',tags:['Творчество','Прогулки','Подкасты'],portrait:3,likesYou:false}];
