function go(path){if(location.hash==='#'+path)render();else location.hash=path}
function link(path,label,cls='text-btn'){return `<button class="${cls}" data-go="${safe(path)}">${label}${icon('arrow')}</button>`}
function ageLabel(age){return ({1:'1 месяц',3:'3 месяца',6:'6 месяцев',12:'12 месяцев и старше'})[age]||'Возраст не выбран'}
function ageRange(age){return ({1:'0–2 месяца',3:'3–5 месяцев',6:'6–11 месяцев',12:'12 месяцев и старше'})[age]}
function formatKind(a){return a.format==='podcast'?'Аудиозаметка':'Статья'}
function topLine(){return `<div class="topline"><button class="header-brand" data-go="home" aria-label="На главную"><img src="assets/logo.png" alt="Четвёртый триместр"></button><button class="icon-btn header-search" aria-label="Найти статью" data-action="search">${icon('search')}</button></div>`}
function pageHead(title,sub,ico='leaf',eye='РЯДОМ С ВАМИ'){return `<div class="page-head"><div><div class="eyebrow">${eye}</div><h1>${title}</h1>${sub?`<p>${sub}</p>`:''}</div><div class="round-icon">${icon(ico)}</div></div>`}
function back(path,label='Назад'){return `<button class="back-btn" data-go="${safe(path)}">${icon('back')}${label}</button>`}
function footer(){return `<div class="footer-note"><span>ЧЕТВЁРТЫЙ ТРИМЕСТР · С ЗАБОТОЙ О ВАС</span><span>В своём темпе. Вместе.</span></div>`}
function art(a,extra=''){return `<div class="article-art ${a.owner==='mom'?'warm':''} ${extra}">${botanical()}<div class="art-symbol">${icon(a.icon)}</div></div>`}
function articleCard(a){return `<button class="article-card" data-go="article/${a.id}">${art(a)}<div class="article-info"><span class="eyebrow">${a.owner==='baby'?'Для малыша':'Для мамы'} · ${a.cat}</span><h3>${a.title}</h3><div class="meta">${icon(a.format==='podcast'?'audio':'clock')}${a.format==='podcast'?'Слушать':'Читать'} · ${a.time} мин</div></div></button>`}
function articleRow(a){return `<button class="article-row" data-go="article/${a.id}"><span class="row-art">${icon(a.icon)}</span><span><span class="eyebrow">${formatKind(a)} · ${a.cat}</span><h3>${a.title}</h3><span class="meta tiny muted">${icon('clock')}${a.time} мин · простыми словами</span></span>${icon('arrow','arrow-icon')}</button>`}
function moodIcon(n){return `<svg viewBox="0 0 28 28" aria-hidden="true"><circle cx="14" cy="14" r="11"/><path d="M10 11h.1M18 11h.1" stroke-width="2"/><path d="${['M9 16q5-4 10 0','M9 16h10','M9 16q5 5 10 0'][n]}"/></svg>`}
const dailyQuotes=['Не нужно быть идеальной, чтобы быть хорошей мамой','Забота о себе начинается с маленького доброго шага','Вам можно отдыхать и просить о помощи','У каждого дня свой ритм. Найдите ваш','Даже маленькие шаги имеют значение','Вы учитесь вместе с малышом. Всему нужно время','Сегодня достаточно быть рядом'];
function home(){const quote=dailyQuotes[Math.floor(Date.now()/86400000)%dailyQuotes.length];const today=new Date().toDateString();const moodToday=state.moodDate===today?state.mood:null;return `${topLine()}<header class="welcome"><div><h1>Добрый день,<br>${safe(state.name)}</h1><p class="quote">«${quote}».</p></div><button class="profile-logo" data-go="profile" aria-label="Открыть мой профиль"><span class="profile-symbol">${icon('user')}</span></button></header><button class="editorial-hero" data-go="article/pause" aria-label="Открыть материал «Можно попросить о помощи»"><img src="assets/quiet-morning.jpg" alt="" loading="eager"><span class="hero-copy"><span class="hero-kicker">Рекомендация для мамы</span><span class="hero-title">Несколько минут<br>для себя</span><span class="hero-action">Открыть материал ${icon('arrow')}</span></span></button><div class="home-columns"><div><div class="eyebrow section-kicker">Что вам сейчас нужно?</div><div class="service-grid">${[['assistant','ai','Помощник ИИ','Можно спросить обо всём'],['community','community','Мамюнити','Свои люди рядом'],['baby','baby','Здоровье ребёнка','Забота шаг за шагом'],['mom','leaf','Здоровье мамы','В своём темпе']].map((s,i)=>`<button class="service service-${i}" data-go="${s[0]}"><span class="watermark">${icon(s[1])}</span><span class="service-icon">${icon(s[1])}</span><h2>${s[2]}</h2><p>${s[3]}</p><span class="arrow">${icon('arrow')}</span></button>`).join('')}</div><div class="support-banner"><div class="eyebrow">Немного времени для себя</div><h2>Вам тоже<br>нужна забота.</h2><p>Побудьте здесь. Сделайте паузу.<br>Остальное может немного подождать.</p>${link('article/pause','Побыть на своей стороне')}${botanical()}</div><div class="section-head"><h2>Сейчас может пригодиться</h2>${link('library','Все материалы')}</div><div class="article-cards">${articleCard(articles[0])}${articleCard(articles.find(a=>a.id==='body'))}</div></div><aside class="home-aside"><section class="daily-card"><div class="eyebrow">Минутка для себя</div><h3>Как вы сегодня?</h3><p>Здесь можно честно.<br>Любое чувство — важное.</p><div class="moods">${['Мне тяжело','По-разному','Мне хорошо'].map((s,n)=>`<button class="mood ${moodToday===n?'selected':''}" data-mood="${n}" aria-label="${s}" aria-pressed="${moodToday===n}">${moodIcon(n)}</button>`).join('')}</div><p class="mood-feedback">${moodToday===null?'Один маленький вопрос о себе.':['Спасибо, что заметили. Поддержка рядом.','Можно чувствовать разное одновременно.','Пусть сегодня будет больше таких моментов.'][moodToday]}${moodToday===0?'<button class="inline-link" data-go="assistant">Поговорить о том, что тяжело</button>':''}</p></section><section class="age-mini"><div class="age-header"><div class="round-icon">${icon('baby')}</div><div><div class="eyebrow">Ваш малыш</div><h3>${state.age?ageLabel(state.age):'Знакомимся ближе'}</h3></div></div><div class="age-line"><span style="width:${state.age?Math.min(state.age/12*100,100):0}%"></span></div><p class="tiny muted">${state.age?'Нужные знания на каждом этапе.':'Укажите возраст — подберём материалы.'}</p>${link('baby',state.age?'Открыть его маленький мир':'Выбрать возраст')}</section><div class="little-note"><div class="quote-mark">“</div><p>Материнство —<br>ваш путь.<br>Проходить его<br>можно вместе.</p>${botanical()}</div></aside></div>${footer()}`}
function categoryCards(owner,items){return `<div class="category-grid">${items.map(([cat,ico])=>{const count=articles.filter(a=>a.owner===owner&&a.cat===cat&&(owner==='mom'||a.ages.includes(state.age))).length;return `<button class="category" data-go="category/${owner}/${encodeURIComponent(cat)}"><div class="round-icon">${icon(ico)}</div>${icon('arrow','corner-arrow')}<h3>${cat}</h3><p>${count} ${count===1?'материал':'материала'} · просто и по делу</p></button>`}).join('')}</div>`}
function baby(){return `${topLine()}${pageHead('Здоровье ребёнка','Понятные ответы о маленьком человеке. Шаг за шагом, вместе с вами.','baby','РАСТЁМ ВМЕСТЕ')}${state.age===null?`<div class="age-intro panel"><div class="round-icon">${icon('baby')}</div><h2>Сколько вашему малышу?</h2><p>Выберите его этап. Покажем то, что важно именно сейчас. Возраст всегда можно изменить.</p><div class="age-choices">${[1,3,6,12].map(n=>`<button class="age-choice" data-age="${n}"><strong>${n===12?'12+':n}</strong><span>${n===1?'месяц':n===3?'месяца':'месяцев'} · ${ageRange(n)}</span></button>`).join('')}</div><p class="tiny" style="margin-top:20px">Материалы для ознакомления. Если малыш родился раньше срока, обсудите этапы развития с педиатром.</p></div>`:`<div class="age-panel"><div><div class="eyebrow">${safe(state.child)} · ВАШ ЭТАП</div><h3>${ageLabel(state.age)}</h3><p class="tiny muted">Подборка для возраста ${ageRange(state.age)}</p></div><button class="secondary" data-action="change-age">Изменить ${icon('down')}</button></div><div class="age-tabs" aria-label="Этап развития">${[1,3,6,12].map(n=>`<button class="${state.age===n?'active':''}" data-age="${n}" aria-pressed="${state.age===n}">${ageLabel(n).replace(' и старше','+')}</button>`).join('')}</div>${categoryCards('baby',cats[state.age])}<div class="info-note">${icon('shield')}<span>Каждый малыш развивается в своём темпе. Материалы помогают разобраться, а личные рекомендации даёт ваш педиатр.</span></div><div class="section-head"><h2>Начать с самого простого</h2></div><div class="article-cards">${articles.filter(a=>a.owner==='baby'&&a.ages.includes(state.age)).slice(0,2).map(articleCard).join('')}</div>`}${footer()}`}
function mom(){return `${topLine()}${pageHead('Здоровье мамы','Вы важны. Ваше тело, ваши чувства и ваше право на заботу.','leaf','ВОЗВРАЩАЕМСЯ К СЕБЕ')}<div class="audio-panel"><button class="play-btn" data-go="article/pause" aria-label="Открыть аудиозаметку Можно попросить о помощи">${icon('play')}</button><div><div class="eyebrow" style="color:#c0c8af">АУДИОЗАМЕТКА · 2 МИНУТЫ</div><h3>Можно попросить о помощи</h3><p>Тёплое напоминание, которое можно послушать.</p></div></div>${categoryCards('mom',momCats)}<div class="section-head"><h2>Для вас, без спешки</h2>${link('library/mom','Все материалы')}</div><div class="article-cards">${articleCard(articles.find(a=>a.id==='body'))}${articleCard(articles.find(a=>a.id==='mind'))}</div>${footer()}`}
function category(){const owner=route[1],cat=decodeURIComponent(route[2]||'');const filtered=articles.filter(a=>a.owner===owner&&a.cat===cat&&(owner==='mom'||a.ages.includes(state.age||1))).filter(a=>articleFilter==='all'||(articleFilter==='podcast'?a.format==='podcast':a.format!=='podcast'));return `${topLine()}${back(owner,owner==='mom'?'Здоровье мамы':'Здоровье ребёнка')}${pageHead(safe(cat),owner==='mom'?'Для вашего самочувствия. Можно читать, можно слушать.':`Материалы для этапа «${ageLabel(state.age||1)}». Никаких сложных слов.`,(momCats.concat(cats[1]).find(c=>c[0]===cat)||[])[1]||'leaf')} ${owner==='mom'?`<div class="filter-row">${[['all','Всё'],['article','Статьи'],['podcast','Аудиозаметки']].map(([id,label])=>`<button class="chip ${articleFilter===id?'active':''}" data-filter="${id}" aria-pressed="${articleFilter===id}">${label}</button>`).join('')}</div>`:''}<div class="list-stack">${filtered.length?filtered.map(articleRow).join(''):'<div class="empty"><h2>Здесь пока тихо</h2><p>В этой категории пока нет аудиозаметок. Можно переключиться на статьи.</p><button class="secondary" data-filter="all">Показать всё</button></div>'}</div><div class="info-note">${icon('info')}<span>Материалы не заменяют личную консультацию. В каждой медицинской статье есть ссылка на источник.</span></div>`}
function article(){const a=articles.find(x=>x.id===route[1]);if(!a)return notFound();const saved=state.saved.includes(a.id);return `${topLine()}<article class="article-reader">${back(`category/${a.owner}/${encodeURIComponent(a.cat)}`,a.cat)}<div class="eyebrow">${a.owner==='mom'?'ЗДОРОВЬЕ МАМЫ':'ЗДОРОВЬЕ РЕБЁНКА'} · ${formatKind(a)}</div><h1>${a.title}</h1><div class="meta tiny muted">${icon('clock')}${a.time} минуты · простыми словами</div><p class="lead">${a.desc}</p>${a.format==='podcast'?`<div class="audio-panel ${audioId===a.id?'playing':''}"><button class="play-btn" data-audio="${a.id}" aria-label="${audioId===a.id?'Остановить':'Слушать'} аудиозаметку">${icon(audioId===a.id?'pause':'play')}</button><div><h3>${audioId===a.id?'Слушаем вместе':'Послушать эту заметку'}</h3><p>Озвучка браузером · текст ниже</p><div class="audio-bars" aria-hidden="true">${'<i></i>'.repeat(27)}</div></div></div>`:art(a,'reader-art')}<h2>${a.format==='podcast'?'О чём эта заметка':'Давайте по шагам'}</h2><div class="steps">${a.steps.map((s,i)=>`<div class="step"><span class="step-number">${i+1}</span><p>${s}</p></div>`).join('')}</div><div class="takeaway"><h3>Самое главное</h3><p>${a.takeaway}</p></div><div class="reader-actions"><button class="${saved?'primary':'secondary'}" data-save-article="${a.id}">${icon(saved?'check':'bookmark')}${saved?'Сохранено':'Сохранить'}</button><button class="secondary" data-go="assistant">${icon('ai')}Задать вопрос</button></div><p class="article-disclaimer">Общая информация, не диагноз и не индивидуальный план лечения.</p><div class="article-source">${a.source?`Источник: <a href="${sources[a.source]}" target="_blank" rel="noopener">NHS · открыть оригинал на английском</a><br>Сверено 26 октября 2026. Пересказ простыми словами. Медицинская редактура перед запуском ещё нужна.`:'Редакционная заметка прототипа. Персональные вопросы о лечении, прививках и средствах ухода обсуждайте с врачом.'}</div></article>`}
function library(){let list=articles;if(route[0]==='saved')list=list.filter(a=>state.saved.includes(a.id));if(route[1]==='mom')list=list.filter(a=>a.owner==='mom');return `${topLine()}${back('home','На главную')}${pageHead(route[0]==='saved'?'Ваши сохранённые':'Библиотека заботы','Короткие материалы, к которым удобно возвращаться.','book')}<div class="list-stack">${list.length?list.map(articleRow).join(''):`<div class="empty"><div class="round-icon">${icon('bookmark')}</div><h2>Ваше важное будет здесь</h2><p>Нажмите «Сохранить» в статье, чтобы вернуться к ней позже.</p><button class="primary" data-go="library">Выбрать материал</button></div>`}</div>`}
function community(){return `${topLine()}${pageHead('Мамюнити','Здесь понимают с полуслова. Найдите свой круг и близких по духу мам.','community','ЛЮДИ, С КОТОРЫМИ ЛЕГЧЕ')}<div class="tabs" aria-label="Разделы сообщества">${[['rooms','Чаты по темам'],['meet','Найти подруг'],['matches','Мои мэтчи']].map(([id,label])=>`<button class="${communityTab===id?'active':''}" data-tab="${id}">${label}${id==='matches'&&state.matches.length?` · ${state.matches.length}`:''}</button>`).join('')}</div>${communityTab==='rooms'?`<div class="info-note" style="margin-top:0">${icon('info')}<span>Демонстрационное сообщество. Профили и сообщения — примеры. Ваши сообщения видны только в этой вкладке.</span></div><div class="room-grid">${rooms.map(([id,title,ico,desc],i)=>`<button class="room-card" data-go="room/${id}"><div class="room-top"><div class="round-icon">${icon(ico)}</div><h3>${title}</h3></div><p>${desc}</p><div class="room-bottom"><span class="member-dots"><span>А</span><span>М</span><span>Е</span></span><span>Демо-чат</span>${icon('arrow')}</div></button>`).join('')}</div>`:communityTab==='meet'?meet():matches()}${footer()}`}
function sharedTags(m){const own=state.interests.toLowerCase();return m.tags.filter(t=>own.includes(t.toLowerCase()))}
function meet(){const available=moms.filter(m=>!state.likes.includes(m.id)).sort((a,b)=>sharedTags(b).length-sharedTags(a).length);const m=available[candidateIndex%Math.max(available.length,1)];if(!m)return `<div class="empty"><div class="round-icon">${icon('heart')}</div><h2>Вы со всеми познакомились</h2><p>Это все демонстрационные анкеты. Посмотрите мэтчи или начните заново.</p><button class="primary" data-action="reset-moms">Посмотреть анкеты снова</button></div>`;return `<div class="match-layout"><div><div class="match-card"><div class="portrait-wrap">${portrait(m.portrait)}<span class="portrait-label">Демо-анкета · иллюстрация</span></div><div class="match-details"><h2>${m.name}, ${m.age}</h2><div class="location">${icon('pin')}${m.city} · ${m.child}</div><p>${m.bio}</p>${sharedTags(m).length?`<p class="tiny" style="margin-top:12px;color:var(--green)">Общее с вами: ${sharedTags(m).join(', ').toLowerCase()}</p>`:''}<div class="tags">${m.tags.map(t=>`<span class="${sharedTags(m).includes(t)?'shared':''}">${t}</span>`).join('')}</div></div></div><div class="match-actions"><button class="match-action" data-skip="${m.id}" aria-label="Следующая анкета">${icon('close')}</button><button class="match-action like" data-like="${m.id}" aria-label="Отметить симпатию: ${m.name}">${icon('heart')}</button></div><p class="tiny muted" style="text-align:center;margin-top:12px">Листайте или смахните карточку. Вправо — симпатия.</p></div><aside class="match-side"><h3>Не идеальная подруга.<br>Просто ваша.</h3><p>Общие интересы, знакомые переживания и желание быть рядом. При взаимной симпатии откроется личный чат.</p><div class="info-note">${icon('shield')}<span>Это пример механики: у Анны и Елены задана взаимная симпатия. Реальные пользователи и геолокация пока не подключены.</span></div><button class="secondary" data-go="profile">${icon('user')}Мои интересы</button></aside></div>`}
function matches(){return state.matches.length?`<div class="list-stack">${state.matches.map(id=>{const m=moms.find(m=>m.id===id);if(!m)return '';return `<button class="article-row" data-go="private/${m.id}"><span class="profile-avatar" style="width:60px;height:60px;margin:0">${portrait(m.portrait)}</span><span><span class="eyebrow">Взаимная симпатия · демо</span><h3>${m.name}</h3><span class="tiny muted">Начните с простого «привет»</span></span>${icon('chat','arrow-icon')}</button>`}).join('')}</div>`:`<div class="empty"><div class="round-icon">${icon('heart')}</div><h2>Свой человек найдётся</h2><p>Когда симпатия будет взаимной, здесь появится личный чат.</p><button class="primary" data-tab="meet">Посмотреть анкеты</button></div>`}
function getRoomMessages(id){if(!roomMessages[id])roomMessages[id]=(initialRoom[id]||[]).map(([name,text],i)=>({name,text,own:false,time:'пример',portrait:i}));return roomMessages[id]}
function messageHTML(m){return `<div class="message ${m.own?'own':''}"><div class="bubble ${m.urgent?'urgent-bubble':''}">${m.name?`<div class="sender">${safe(m.name)}</div>`:''}${safe(m.text).replace(/\n/g,'<br>')}${m.articleId?`<br><button class="inline-link" data-go="article/${m.articleId}">Открыть материал →</button>`:''}${m.sourceUrl?`<a class="bot-source" href="${safe(m.sourceUrl)}" target="_blank" rel="noopener noreferrer">Источник: NHS ↗</a>`:''}${m.quickReplies?.length?`<div class="reply-options">${m.quickReplies.map(q=>`<button data-quick="${safe(q)}">${safe(q)}</button>`).join('')}</div>`:''}<span class="message-time">${safe(m.time||'сейчас')}</span></div></div>`}
function compose(type,id=''){return `<form class="chat-compose" data-chat="${type}" data-chat-id="${safe(id)}"><label class="sr-only" for="message-input">Ваше сообщение</label><textarea id="message-input" name="message" maxlength="2000" rows="1" placeholder="Напишите сообщение…" required></textarea><button class="send" type="submit" aria-label="Отправить сообщение">${icon('send')}</button></form>`}
function room(){const r=rooms.find(r=>r[0]===route[1]);if(!r)return notFound();return `${back('community','Все чаты')}<div class="chat-layout"><div class="chat-top"><div class="round-icon">${icon(r[2])}</div><div><h3>${r[1]}</h3><div class="status-line">Демо-участницы · без реального соединения</div></div><button class="text-btn" data-action="community-rules">Правила</button></div><div class="chat-scroll"><div class="chat-day">Пример беседы · сообщения не отправляются другим людям</div>${getRoomMessages(r[0]).map(messageHTML).join('')}</div>${compose('room',r[0])}<div class="chat-footnote">Опыт мам — поддержка, а не медицинское назначение.</div></div>`}
function privateChat(){const m=moms.find(m=>m.id===route[1]);if(!m||!state.matches.includes(m.id))return notFound();const msgs=privateMessages[m.id]||[];return `${back('community','Мои мэтчи')}<div class="chat-layout"><div class="chat-top"><span class="profile-avatar" style="width:40px;height:40px;margin:0">${portrait(m.portrait)}</span><div><h3>${m.name}</h3><div class="status-line">Взаимная симпатия · демо</div></div></div><div class="chat-scroll"><div class="chat-day">Вы понравились друг другу. Можно начать знакомство.</div>${msgs.length?msgs.map(messageHTML).join(''):`<div class="empty"><h2>Начните с общего</h2><p>Вы обе любите ${safe(m.tags[0].toLowerCase())}. Что если предложить прогулку?</p><button class="secondary" data-private-quick="Привет! Вижу, у нас есть общие интересы. Буду рада познакомиться ">Привет, давай знакомиться!</button></div>`}</div>${compose('private',m.id)}<div class="chat-footnote">Локальный демо-чат. ${m.name} — вымышленный профиль.</div></div>`}
function supportHTML(){return `<section class="support-alert" role="alert"><div class="eyebrow" style="color:#88694d">СЕЙЧАС ВАЖНА ЖИВАЯ ПОДДЕРЖКА</div><h3>Не оставайтесь с этим одна</h3><p>Спасибо, что сказали. Если есть риск навредить себе или ребёнку прямо сейчас:</p><ol><li>Положите малыша на спину в безопасную кроватку без мягких предметов или передайте надёжному взрослому. Не трясите ребёнка.</li><li>Отойдите от опасных предметов. Позовите близкого взрослого и скажите прямо: «Мне нужна помощь, побудь со мной и ребёнком».</li><li>Позвоните в экстренную службу, если можете действовать по этим мыслям, уже причинили вред или слышите приказывающие голоса. Не ждите ответа в приложении.</li></ol><a class="primary" href="tel:112" style="text-decoration:none">${icon('phone')}Позвонить 112 · Россия и ЕС</a><br><button class="secondary" data-action="psychologist">${icon('user')}Помощь специалиста</button><p class="support-status">Это прототип: психолог не подключён, запрос и переписка никому не отправлены. В другой стране используйте местный экстренный номер.</p></section>`}
function assistant(){return `${topLine()}<div class="chat-layout"><div class="chat-top"><div class="round-icon">${icon('ai')}</div><div><h1 class="chat-title">Помощник ИИ</h1><div class="status-line">Базовый помощник · работает без интернета</div></div><button class="text-btn" data-action="psychologist">Нужен человек</button></div><div class="chat-scroll">${aiMessages.length?'':`<div class="assistant-intro"><div class="round-icon">${icon('ai')}</div><div class="eyebrow" style="margin-bottom:10px">ОДИН ВОПРОС — УЖЕ НАЧАЛО</div><h2>О чём вы думаете?</h2><p>О малыше, о себе, о том, что тревожит.<br>Здесь можно начать с любого вопроса.</p></div>`}<div class="chat-day">Без медицинских назначений · история хранится только в этой вкладке</div>${aiMessages.map(messageHTML).join('')}${crisis?supportHTML():''}</div>${aiMessages.length?'':`<div class="quick-questions">${['Как подмывать малыша?','Как попросить о помощи?','Что почитать о кормлении?'].map(s=>`<button data-quick="${s}">${s}</button>`).join('')}</div>`}${compose('ai')}<div class="chat-footnote">Ответы по проверенным материалам, без нейросети. Не заменяет врача. Специалист не подключён.</div></div>`}
function profile(){return `${topLine()}${back('home','На главную')}${pageHead('Моё пространство','Немного о вас — чтобы забота была ближе.','user','ЛИЧНЫЙ ПРОФИЛЬ')}<div class="profile-layout"><div class="panel profile-card"><div class="profile-avatar">${portrait(0)}</div><div><h2>${safe(state.name)}</h2><p class="small muted">${safe(state.city)}</p><div class="tags"><span>В своём темпе</span><span>Мама</span></div></div><div class="profile-links"><button data-go="saved">${icon('bookmark')}Сохранённое <span class="end tiny">${state.saved.length}</span></button><button data-action="privacy">${icon('shield')}Ваши данные ${icon('arrow','end')}</button><button data-action="reset-data">${icon('trash')}Сбросить демоданные</button></div></div><section class="panel"><h3 style="margin-bottom:24px">Знакомимся ближе</h3><form id="profile-form" class="form-grid"><label class="field">Как к вам обращаться<input name="name" maxlength="30" value="${safe(state.name)}" required autocomplete="given-name"></label><div class="form-row"><label class="field">Как зовут малыша<input name="child" maxlength="30" value="${safe(state.child)}" required></label><label class="field">Город<input name="city" maxlength="60" value="${safe(state.city)}" required autocomplete="address-level2"></label></div><label class="field">Этап малыша<select name="age"><option value="">Ещё не выбран</option>${[1,3,6,12].map(n=>`<option value="${n}" ${state.age===n?'selected':''}>${ageLabel(n)} (${ageRange(n)})</option>`).join('')}</select></label><label class="field">Ваши интересы<textarea name="interests" maxlength="200">${safe(state.interests)}</textarea></label><p class="tiny muted">В прототипе изменения сохраняются только в этом браузере. Не вводите реальные медицинские или контактные данные.</p><button type="submit" class="primary">${icon('check')}Сохранить изменения</button></form></section></div><div class="profile-links mobile-profile-links"><button data-go="saved">${icon('bookmark')}Мои сохранённые материалы <span class="end">${state.saved.length}</span></button><button data-action="privacy">${icon('shield')}Где хранятся мои данные ${icon('arrow','end')}</button><button data-action="reset-data">${icon('trash')}Сбросить демоданные</button></div>`}
function notFound(){return `${topLine()}<div class="empty"><h2>Страница не нашлась</h2><p>Давайте вернёмся в ваше пространство.</p><button class="primary" data-go="home">На главную</button></div>`}
function nav(){const active=route[0]==='article'?(articles.find(a=>a.id===route[1])?.owner||'home'):route[0]==='category'?route[1]:['room','private'].includes(route[0])?'community':route[0];$('#sidebar').innerHTML=`<nav class="side-links" aria-label="Основная навигация">${navItems.map(([id,ico,title])=>`<button data-go="${id}" class="${active===id?'active':''}" ${active===id?'aria-current="page"':''}>${icon(ico)}${title}</button>`).join('')}<button data-go="profile" class="${active==='profile'?'active':''}">${icon('user')}Мой профиль</button></nav><div class="sidebar-bottom">${icon('leaf')}<p>У каждой мамы<br>есть право<br>на поддержку.</p><span class="demo-label">ИНТЕРАКТИВНЫЙ ПРОТОТИП</span></div>`;$('#bottom-nav').innerHTML=navItems.map(([id,ico,title,short])=>`<button data-go="${id}" class="${active===id?'active':''}" ${active===id?'aria-current="page"':''} aria-label="${title}">${icon(ico)}<span>${short}</span></button>`).join('')}
function render(opts={}){route=(location.hash.slice(1)||'home').split('/');const pages={home,baby,mom,profile,category,article,community,room,private:privateChat,assistant,library,saved:library};$('#main').innerHTML=`<div class="page-enter">${(pages[route[0]]||notFound)()}</div>`;nav();document.title=(route[0]==='home'?'Рядом с вами':({baby:'Здоровье ребёнка',mom:'Здоровье мамы',community:'Мамюнити',assistant:'Помощник ИИ',profile:'Мой профиль',article:articles.find(a=>a.id===route[1])?.title}[route[0]]||'Ваше пространство'))+' · Четвёртый триместр';if(!opts.keepScroll)window.scrollTo(0,0);if(['room','private','assistant'].includes(route[0])){const sc=$('.chat-scroll');if(sc)sc.scrollTop=sc.scrollHeight} }
function toast(text){const el=$('#toast');el.textContent=text;el.classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>el.classList.remove('show'),3300)}
function openModal(title,body){lastFocus=document.activeElement;const m=$('#modal');m.innerHTML=`<div class="modal-top"><h2>${title}</h2><button class="icon-btn" data-action="close-modal" aria-label="Закрыть окно">${icon('close')}</button></div>${body}`;m.showModal()}
function closeModal(){$('#modal').close();lastFocus?.focus?.()}
function ageModal(){openModal('Какой сейчас этап?',`<p class="small muted">Возраст меняет подборку, а не задаёт норму развития.</p><div class="age-choices">${[1,3,6,12].map(n=>`<button class="age-choice" data-age="${n}"><strong>${n===12?'12+':n}</strong><span>${ageRange(n)}</span></button>`).join('')}</div>`)}
function searchModal(){openModal('Что вас интересует?',`<label class="sr-only" for="article-search">Поиск по статьям</label><input class="search-input" id="article-search" type="search" placeholder="Например, кормление или сон" autocomplete="off"><div class="search-results">${searchResults('')}</div>`);setTimeout(()=>$('#article-search')?.focus(),30)}
function searchResults(q){const a=articles.filter(a=>(a.title+' '+a.cat+' '+a.desc).toLowerCase().includes(q.toLowerCase()));return a.length?a.slice(0,8).map(a=>`<button data-go="article/${a.id}" data-close><p>${a.cat} · ${formatKind(a)}</p><h3>${a.title}</h3></button>`).join(''):'<p class="small muted">Пока ничего не найдено. Попробуйте «гигиена», «кормление» или «помощь».</p>'}
function requestPsychologist(){openModal('Когда нужен человек',`<p class="small">В полной версии здесь будет подключение дежурного специалиста с понятным временем ожидания и согласием на передачу переписки.</p><div class="info-note">${icon('info')}<span>Сейчас служба не подключена. Никто не получил уведомление или вашу переписку. Не ждите ответа в приложении.</span></div><p class="small muted">Если вам тяжело, свяжитесь с врачом или знакомым специалистом и позовите близкого человека. При риске немедленного вреда себе или ребёнку нужна экстренная помощь.</p><a class="primary wide" style="margin-top:20px;text-decoration:none" href="tel:112">${icon('phone')}112 · экстренная помощь в России и ЕС</a><p class="tiny muted" style="margin-top:12px">В других странах используйте местную экстренную службу.</p>`)}
function timeNow(){return new Date().toLocaleTimeString('ru-RU',{hour:'2-digit',minute:'2-digit'})}
function risk(text){const t=text.toLowerCase().replace(/ё/g,'е');return /уби[тй]|убью|убье|задуш|удуш|суицид|самоуб|себя.{0,15}(порез|повред|вред)|порезать.{0,10}(себя|вены)|навред.{0,25}(себе|ребен|малыш)|вред.{0,20}(себе|ребен|малыш)|боюсь.{0,20}(сорв|удар|сделаю)|удар.{0,20}(ребен|малыш)|не хочу жить|не хочется жить|хочу умереть|лучше.{0,8}умер|хочу исчезнуть|выброс.{0,15}(ребен|малыш)|голос.{0,30}(приказ|вел|говор)|хочу.{0,10}(прыгнуть|сдохнуть)|потряс.{0,15}(ребен|малыш)/i.test(t)}
function sendAI(text){
  aiMessages.push({own:true,text,time:timeNow()});
  const response=TrimesterBot.reply(text,botSession,articles,state,risk);
  crisis=Boolean(response.crisis);
  aiMessages.push({ai:true,name:'Помощник',...response,time:timeNow()});
  render({keepScroll:true});$('#message-input')?.focus();
}
function startAudio(id){if(!('speechSynthesis' in window)){toast('Браузер не поддерживает озвучку. Текст заметки доступен ниже.');return}if(audioId===id){speechSynthesis.cancel();audioId=null;render({keepScroll:true});return}speechSynthesis.cancel();const a=articles.find(a=>a.id===id);const u=new SpeechSynthesisUtterance([a.title,a.desc,...a.steps,a.takeaway].join('. '));u.lang='ru-RU';u.rate=.87;const v=speechSynthesis.getVoices().find(v=>v.lang.startsWith('ru'));if(v)u.voice=v;u.onend=()=>{audioId=null;if(route[0]==='article'&&route[1]===id)render({keepScroll:true})};u.onerror=()=>{audioId=null;toast('Не удалось запустить озвучку. Текст можно прочитать ниже.');if(route[0]==='article')render({keepScroll:true})};audioId=id;speechSynthesis.speak(u);render({keepScroll:true})}
document.addEventListener('click',e=>{const el=e.target.closest('button,a');if(!el)return;if(el.hasAttribute('data-go')){if(el.hasAttribute('data-close')&&$('#modal').open)closeModal();if(route[0]==='private'&&el.dataset.go==='community')communityTab='matches';articleFilter='all';go(el.dataset.go);return}if(el.hasAttribute('data-age')){state.age=Number(el.dataset.age);save();if($('#modal').open)closeModal();render({keepScroll:true});toast('Подборка обновлена: '+ageLabel(state.age));return}if(el.hasAttribute('data-mood')){state.mood=Number(el.dataset.mood);state.moodDate=new Date().toDateString();save();render({keepScroll:true});return}if(el.hasAttribute('data-filter')){articleFilter=el.dataset.filter;render({keepScroll:true});return}if(el.hasAttribute('data-tab')){communityTab=el.dataset.tab;render({keepScroll:true});return}if(el.hasAttribute('data-save-article')){const id=el.dataset.saveArticle;state.saved=state.saved.includes(id)?state.saved.filter(x=>x!==id):[...state.saved,id];save();render({keepScroll:true});toast(state.saved.includes(id)?'Сохранено в вашем профиле':'Удалено из сохранённого');return}if(el.hasAttribute('data-quick')){sendAI(el.dataset.quick);return}if(el.hasAttribute('data-private-quick')){privateMessages[route[1]]=[...(privateMessages[route[1]]||[]),{own:true,text:el.dataset.privateQuick,time:timeNow()}];render({keepScroll:true});return}if(el.hasAttribute('data-skip')){candidateIndex++;render({keepScroll:true});return}if(el.hasAttribute('data-like')){const m=moms.find(m=>m.id===el.dataset.like);state.likes.push(m.id);if(m.likesYou&&!state.matches.includes(m.id)){state.matches.push(m.id);save();render({keepScroll:true});openModal('Взаимная симпатия',`<div class="match-celebration"><div class="hearts">♡</div><h2>Кажется, вы свои.</h2><p>Вы с ${m.name==='Анна'?'Анной':'Еленой'} понравились друг другу.<br>Можно начать с простого «привет».<br><span class="tiny">Это демонстрационный мэтч.</span></p><button class="primary wide" data-go="private/${m.id}" data-close>${icon('chat')}Начать разговор</button></div>`)}else{save();render({keepScroll:true});toast('Симпатия отмечена. Чат откроется при взаимном интересе.')}return}if(el.hasAttribute('data-audio')){startAudio(el.dataset.audio);return}switch(el.dataset.action){case'search':searchModal();break;case'close-modal':closeModal();break;case'change-age':ageModal();break;case'psychologist':requestPsychologist();break;case'community-rules':openModal('Бережно друг к другу',`<div class="steps"><div class="step"><span class="step-number">1</span><p>Без осуждения, сравнения детей и оценок «хорошая / плохая мама».</p></div><div class="step"><span class="step-number">2</span><p>Делитесь своим опытом. Не назначайте лечение и не публикуйте личные данные других людей.</p></div><div class="step"><span class="step-number">3</span><p>Если есть угроза здоровью, обращайтесь к врачу или в экстренную службу. Чат не заменяет помощь.</p></div></div><p class="tiny muted">В этой версии чаты демонстрационные. Реальная модерация ещё не подключена.</p>`);break;case'reset-moms':state.likes=[];state.matches=[];candidateIndex=0;save();render({keepScroll:true});break;case'privacy':openModal('Ваше маленькое пространство',`<p class="small">Имя, город, возрастной этап малыша, интересы, настроение, сохранённые статьи и демо-мэтчи записываются в локальное хранилище этого браузера.</p><p class="small" style="margin-top:15px">Переписка хранится только в памяти открытой вкладки и исчезает при обновлении страницы. Аккаунты, серверные чаты, геолокация и специалист не подключены.</p><p class="small" style="margin-top:15px">На общем устройстве эти локальные данные могут быть доступны другим людям. Их можно удалить кнопкой «Сбросить демоданные» в профиле.</p>`);break;case'reset-data':openModal('Начать с чистого листа?',`<p class="small muted">Будут удалены данные этого прототипа в браузере: профиль, возраст, сохранённое, настроение и демо-мэтчи. Переписка в этой вкладке тоже очистится.</p><button class="primary wide" style="margin-top:22px" data-action="confirm-reset">Сбросить демоданные</button>`);break;case'confirm-reset':try{localStorage.removeItem('trimester-v1')}catch{}Object.assign(state,structuredClone(defaults));state.saved=[];state.likes=[];state.matches=[];aiMessages.length=0;Object.keys(roomMessages).forEach(k=>delete roomMessages[k]);Object.keys(privateMessages).forEach(k=>delete privateMessages[k]);crisis=false;closeModal();render();toast('Демоданные сброшены');break}});
document.addEventListener('submit',e=>{if(e.target.id==='profile-form'){e.preventDefault();const fd=new FormData(e.target);for(const key of ['name','child','city','interests'])state[key]=String(fd.get(key)||'').trim();if(!state.name||!state.child||!state.city){toast('Заполните имя, имя малыша и город');return}state.age=fd.get('age')?Number(fd.get('age')):null;save();render({keepScroll:true});toast('Изменения сохранены');return}if(e.target.hasAttribute('data-chat')){e.preventDefault();const input=e.target.querySelector('textarea');const text=input.value.trim();if(!text)return;const type=e.target.dataset.chat,id=e.target.dataset.chatId;if(type==='ai')sendAI(text);else{const list=type==='room'?getRoomMessages(id):(privateMessages[id]||(privateMessages[id]=[]));list.push({own:true,text,time:timeNow()});render({keepScroll:true});$('#message-input')?.focus();toast('Сообщение добавлено только в демо-чат')}}});
document.addEventListener('input',e=>{if(e.target.id==='article-search')$('.search-results').innerHTML=searchResults(e.target.value)});
document.addEventListener('keydown',e=>{if(e.target.id==='message-input'&&e.key==='Enter'&&!e.shiftKey&&!e.isComposing){e.preventDefault();e.target.closest('form').requestSubmit()}});
$('#modal').addEventListener('click',e=>{if(e.target===$('#modal')){const r=e.target.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)closeModal()}});
window.addEventListener('hashchange',()=>{if(audioId&&'speechSynthesis'in window){speechSynthesis.cancel();audioId=null}articleFilter='all';render();$('#main').focus({preventScroll:true})});
render();

let swipeStart=null;document.addEventListener('pointerdown',e=>{if(e.target.closest('.match-card'))swipeStart={x:e.clientX,y:e.clientY}});document.addEventListener('pointerup',e=>{if(!swipeStart)return;const dx=e.clientX-swipeStart.x,dy=e.clientY-swipeStart.y;swipeStart=null;if(Math.abs(dx)>65&&Math.abs(dy)<70)document.querySelector(dx>0?'[data-like]':'[data-skip]')?.click()});
